// </dict>
// </plist>
// ```

// ### 4.2 iOS Background Capabilities (`ios/Runner/Info.plist`)
// Required for Driver Location Tracking and FCM Background Notifications:

// ```xml
// <key>UIBackgroundModes</key>
// <array>
//     <string>fetch</string>
//     <string>remote-notification</string>
//     <string>location</string>
// </array>
// <key>NSLocationWhenInUseUsageDescription</key>
// <string>FleetRunner requires GPS location to detect nearby market dispatch orders.</string>
// <key>NSLocationAlwaysAndWhenInUseUsageDescription</key>
// <string>FleetRunner streams vehicle telemetry for live route navigation and customer tracking.</string>
// <key>NSCameraUsageDescription</key>
// <string>FleetRunner uses the camera to capture Proof of Delivery (POD) photos on customer doorstep.</string>
// ```

// ---

// ## 5. Setup & CLI Quick Start Commands

// ```bash
// # 1. Install Firebase CLI & FlutterFire CLI
// npm install -g firebase-tools
// firebase login
// dart pub global activate flutterfire_cli

// # 2. Add dependencies to pubspec.yaml
// flutter pub add firebase_core firebase_auth cloud_firestore firebase_storage firebase_messaging firebase_crashlytics

// # 3. Auto-configure Firebase project across Android & iOS
// flutterfire configure \
//   --project=fleetrunner-courier-prod \
//   --out=lib/firebase_options.dart \
//   --ios-bundle-id=io.fleetrunner.driver \
//   --android-package-name=io.fleetrunner.driver
// ```
